#include <iostream>
#include <vector>
#include <queue>
using namespace std;

class Graph {
private:
    vector<vector<int>> adj;
    int V;

public:
    Graph(int v) {
        V = v;
        adj.resize(v);
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u); // remove for directed graph
    }

    void bfs(int start) {
        vector<bool> visited(V, false);
        queue<int> q;

        // Mark visited BEFORE enqueuing — not after dequeuing
        visited[start] = true;
        q.push(start);

        while (!q.empty()) {
            int node = q.front(); // dequeue from front (FIFO)
            q.pop();

            cout << node << " ";

            for (int neighbour : adj[node]) {
                if (!visited[neighbour]) {
                    visited[neighbour] = true;
                    q.push(neighbour);
                }
            }
        }
    }
};

int main() {
    Graph g(8);

    g.addEdge(1,2);
    g.addEdge(1,3);
    g.addEdge(2,4);
    g.addEdge(4,5);
    g.addEdge(3,6);
    g.addEdge(6,7);

    g.bfs(1);

    return 0;
}

vector<int> bfsDistance(int start) {
    vector<int> dist(V, -1);   // -1 means not visited
    queue<int> q;

    dist[start] = 0;
    q.push(start);

    while (!q.empty()) {
        int node = q.front();
        q.pop();

        for (int neighbour : adj[node]) {
            if (dist[neighbour] == -1) {
                dist[neighbour] = dist[node] + 1; // one step further
                q.push(neighbour);
            }
        }
    }

    return dist;  // dist[i] = shortest hops from start to i
}
